package com.gamehub;
import com.gamehub.application.*; import com.gamehub.domain.Role; import com.gamehub.infrastructure.*; import org.junit.jupiter.api.*; import java.nio.file.*; import static org.junit.jupiter.api.Assertions.*;
class MembershipPaymentRegressionTest { @Test void unpaidMembershipPlanIsPendingUntilStaffSettlement() throws Exception {Path p=Files.createTempFile("membership-pay-", ".db");try(Database db=new Database(p)){var us=new UserService(db);us.bootstrap("manager","password1");var customer=us.registerCustomer("Customer","c@example.com","03001234567","password2");var staff=us.provision("manager","password1","staff","password3",Role.STAFF);var o=new OperationsService(db);long charge=o.subscribeOrRenew(customer.id(),"GOLD");assertTrue(o.charges(customer.id()).get(0).contains("UNPAID"));assertEquals("NONE",o.membership(customer.id()));o.payChargeAsStaff(staff.id(),charge,5000,"CASH","membership-1");assertTrue(o.membership(customer.id()).startsWith("GOLD"));}finally{Files.deleteIfExists(p);}}}
